-- 630: Original BrillaPrep flashcards, batch flashcard-decks-sprint3-001, part 2 of 3.
-- Curriculum-aligned revision content; not official WAEC or NaCCA material.
PRAGMA foreign_keys = ON;
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_electrochemistry_01', 'deck_sys_topic_electrochemistry', 'What is electrolysis?', 'The decomposition of an electrolyte — a molten or aqueous ionic compound — by passing a direct electric current through it.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_electrochemistry_02', 'deck_sys_topic_electrochemistry', 'What is an electrolyte? Give two examples.', 'A substance which, when molten or dissolved in water, conducts electricity and is decomposed by it — e.g. sodium chloride solution and dilute sulphuric acid. (Metals such as copper conduct but are not electrolytes, because they are not decomposed.)', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_electrochemistry_03', 'deck_sys_topic_electrochemistry', 'In electrolysis, which electrode is the anode, and which ions migrate to it?', 'The anode is the positive electrode; negatively charged anions migrate to it and are discharged there. The cathode is the negative electrode and attracts the positively charged cations.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_electrochemistry_04', 'deck_sys_topic_electrochemistry', 'State what happens at each electrode during electrolysis in terms of oxidation and reduction.', 'Oxidation (loss of electrons) occurs at the anode, where anions discharge; reduction (gain of electrons) occurs at the cathode, where cations discharge. Memory aid: OIL RIG — Oxidation Is Loss, Reduction Is Gain.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_electrochemistry_05', 'deck_sys_topic_electrochemistry', 'Name the products of the electrolysis of molten sodium chloride, with the half-equations.', 'Sodium metal at the cathode: Na⁺ + e⁻ → Na; chlorine gas at the anode: 2Cl⁻ → Cl₂ + 2e⁻.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_electrochemistry_06', 'deck_sys_topic_electrochemistry', 'Name the products of the electrolysis of concentrated sodium chloride solution (brine) using inert electrodes.', 'Hydrogen at the cathode, chlorine at the anode, and sodium hydroxide left in solution — the basis of the chlor-alkali industry.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_electrochemistry_07', 'deck_sys_topic_electrochemistry', 'State Faraday’s first law of electrolysis.', 'The mass of a substance discharged (deposited or liberated) at an electrode is directly proportional to the quantity of electricity passed: m ∝ Q, where Q = It.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_electrochemistry_08', 'deck_sys_topic_electrochemistry', 'What quantity of electricity deposits one mole of a singly charged ion such as Ag⁺?', 'One faraday, 96,500 coulombs — the charge on one mole of electrons. A doubly charged ion such as Cu²⁺ needs two faradays (2 × 96,500 C) per mole deposited.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_electrochemistry_09', 'deck_sys_topic_electrochemistry', 'Describe the set-up for electroplating an iron spoon with silver.', 'The spoon is made the cathode, a rod of pure silver the anode, and a solution of a silver salt (e.g. silver nitrate) the electrolyte; silver dissolves from the anode and deposits in an even layer on the spoon.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_electrochemistry_10', 'deck_sys_topic_electrochemistry', 'How is impure copper purified by electrolysis?', 'The impure copper is made the anode, a thin sheet of pure copper the cathode, and copper(II) sulphate solution the electrolyte; copper dissolves from the anode and deposits on the cathode, while less reactive impurities fall as anode mud.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_electrochemistry_11', 'deck_sys_topic_electrochemistry', 'How is aluminium extracted from its oxide, and why must electrolysis be used?', 'Aluminium is too reactive for carbon reduction, so aluminium oxide is dissolved in molten cryolite (to lower the working temperature) and electrolysed: aluminium forms at the carbon cathode and oxygen at the carbon anodes, which burn away.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_electrochemistry_12', 'deck_sys_topic_electrochemistry', 'State three factors that determine which ion is preferentially discharged at an electrode.', 'The position of the ion in the electrochemical (discharge) series, the relative concentration of the ions in solution, and the nature of the electrodes (inert or active).', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_equilibrium_01', 'deck_sys_topic_equilibrium', 'What is a reversible reaction? Give one example.', 'A reaction in which the products can react to re-form the reactants, so the reaction proceeds in both directions — e.g. N₂ + 3H₂ ⇌ 2NH₃ in the Haber process.', NULL, NULL, 1);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_equilibrium_02', 'deck_sys_topic_equilibrium', 'Define dynamic equilibrium in a chemical system.', 'The state reached in a closed system when the forward and reverse reactions occur at equal rates, so the concentrations of reactants and products remain constant even though both reactions continue.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_equilibrium_03', 'deck_sys_topic_equilibrium', 'Why must a system be closed for a chemical equilibrium to be established?', 'So that no reactant or product can escape or be added; in an open system the loss of a product (for example a gas) drives the forward reaction towards completion instead of a balance.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_equilibrium_04', 'deck_sys_topic_equilibrium', 'State Le Chatelier’s principle.', 'If a constraint — a change of concentration, pressure or temperature — is imposed on a system at equilibrium, the system adjusts itself so as to annul (oppose) the constraint.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_equilibrium_05', 'deck_sys_topic_equilibrium', 'Predict the effect of adding more reactant to a system at equilibrium.', 'The equilibrium shifts to the right (towards the products), consuming part of the added reactant until a new equilibrium position is established.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_equilibrium_06', 'deck_sys_topic_equilibrium', 'For N₂(g) + 3H₂(g) ⇌ 2NH₃(g), what is the effect of increasing the pressure?', 'The equilibrium shifts to the right: the side with fewer gas molecules (2 mol of NH₃ against 4 mol of reactants) is favoured, which reduces the pressure.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_equilibrium_07', 'deck_sys_topic_equilibrium', 'For an exothermic reaction at equilibrium, what is the effect of raising the temperature?', 'The equilibrium shifts to the left (towards the reactants): the system favours the reverse, endothermic direction to absorb the added heat, so the yield of product falls.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_equilibrium_08', 'deck_sys_topic_equilibrium', 'What is the effect of a catalyst on a system at equilibrium?', 'No shift in position: a catalyst speeds up the forward and reverse reactions equally, so equilibrium is reached faster but the equilibrium composition is unchanged.', NULL, NULL, 2);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_equilibrium_09', 'deck_sys_topic_equilibrium', 'State the industrial conditions used in the Haber process for manufacturing ammonia.', 'A temperature of about 450 °C (a compromise between rate and yield), a high pressure of about 200 atm, an iron catalyst, and nitrogen and hydrogen in a 1 : 3 ratio; the ammonia formed is liquefied and removed.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_equilibrium_10', 'deck_sys_topic_equilibrium', 'Write the expression for the equilibrium constant Kc for aA + bB ⇌ cC + dD.', 'Kc = [C]ᶜ[D]ᵈ / [A]ᵃ[B]ᵇ, where the square brackets denote equilibrium concentrations in mol/dm³ and the powers are the balancing numbers of the equation.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_equilibrium_11', 'deck_sys_topic_equilibrium', 'What does the magnitude of Kc tell you about an equilibrium?', 'A large Kc (≫ 1) means products predominate — the equilibrium lies well to the right; a small Kc (≪ 1) means reactants predominate — it lies to the left. Kc changes only with temperature.', NULL, NULL, 3);
INSERT OR IGNORE INTO flashcards (id, deck_id, front, back, image_url, hint, difficulty) VALUES ('fc_s3_equilibrium_12', 'deck_sys_topic_equilibrium', 'List three observable characteristics of a system at dynamic equilibrium.', 'The concentrations of all species remain constant; the rates of the forward and reverse reactions are equal; and macroscopic properties such as colour, pressure and density are constant, even though molecular activity continues.', NULL, NULL, 2);
